# -- verification primitives -------------------------------------------
@staticmethod
def _descriptor_consistent(descriptor: dict, allow_undescribed: bool):
    """Whether one on-disk mirror descriptor is internally well-formed.

    A descriptor is the cross-index of an attempt, so every reference it
    carries must already be self-consistent before it is compared against
    anything else:

    * ``kind`` (once described) is one of the four mirrored mutations and
      ``action`` is exactly the audit action that kind commits with;
    * ``write_set`` is a list of unique canonical key ids with the kind's
      exact shape (rotate/import one key; batch a non-empty set; restore a
      possibly empty set);
    * ``handles`` is a duplicate-free list of non-empty
      ``{provider_id, handle}`` pairs;
    * the journal/snapshot references name the operation itself and a
      snapshot only accompanies a batch rotation.

    ``allow_undescribed`` admits a still-``bound`` mirror that crashed
    before ``describe`` (kind/action unset, empty write set).
    """
    if not isinstance(descriptor, dict):
        return False
    operation_id = descriptor.get("operation_id")
    if not _is_uuid4(operation_id):
        return False
    for field in ("tenant_id", "operator_id", "path", "request_body"):
        value = descriptor.get(field)
        if not isinstance(value, str):
            return False
    if not descriptor.get("tenant_id"):
        return False
    kind = descriptor.get("kind")
    action = descriptor.get("action")
    write_set = descriptor.get("write_set")
    if kind is None:
        if not allow_undescribed:
            return False
        if action is not None or write_set:
            return False
    else:
        if kind not in _KIND_ACTIONS or action != _KIND_ACTIONS[kind]:
            return False
        if not ArtifactStore._valid_write_set_shape(kind, write_set):
            return False
    # A read-only kind (encrypt) mints nothing: any handle, provision
    # journal, batch snapshot, restore marker or policy fact on its mirror
    # is by construction an inconsistency.
    if kind in _READ_ONLY_KINDS:
        if descriptor.get("handles"):
            return False
        if descriptor.get("journal") is not None:
            return False
        if descriptor.get("snapshot") is not None:
            return False
        if descriptor.get("empty_marker") is not None:
            return False
        if descriptor.get("policy"):
            return False
    journal = descriptor.get("journal")
    if journal is not None and journal != operation_id:
        return False
    snapshot = descriptor.get("snapshot")
    if snapshot is not None:
        if snapshot != operation_id or kind != "batch_rotate":
            return False
    empty_marker = descriptor.get("empty_marker")
    if empty_marker is not None and not isinstance(empty_marker, str):
        return False
    if not isinstance(descriptor.get("policy"), bool):
        return False
    handles = descriptor.get("handles")
    if not isinstance(handles, list):
        return False
    seen = set()
    for entry in handles:
        if not isinstance(entry, dict):
            return False
        provider_id = entry.get("provider_id")
        handle = entry.get("handle")
        if (
            not isinstance(provider_id, str)
            or not provider_id
            or not isinstance(handle, str)
            or not handle
        ):
            return False
        pair = (provider_id, handle)
        if pair in seen:
            return False
        seen.add(pair)
    return True

@staticmethod
def _valid_write_set_shape(kind: str, write_set) -> bool:
    """The kind's exact write-set shape (unique canonical UUID4s)."""
    if not isinstance(write_set, list):
        return False
    seen = set()
    for key_id in write_set:
        if not _is_key_id(key_id) or key_id in seen:
            return False
        seen.add(key_id)
    if kind in ("rotate", "import", "encrypt") and len(seen) != 1:
        return False
    if kind == "batch_rotate" and not seen:
        return False
    return True

@staticmethod
def _details_correspond(descriptor: dict, record) -> bool:
    """Whether the operation record's durable details match the mirror.

    The kind/action must correspond to the exact ``key_id`` (rotate/
    import), ``items`` set (batch rotation) or ``key_ids`` plus policy
    flag (restore) the executor persisted in ``operations/<id>.json``.
    A mirror that was never described has nothing yet to correspond.
    """
    kind = descriptor.get("kind")
    if kind is None:
        return True
    details = getattr(record, "details", None)
    if not isinstance(details, dict) or details.get("kind") != kind:
        return False
    write_set = descriptor.get("write_set") or []
    if kind in ("rotate", "import", "encrypt"):
        return details.get("key_id") == (write_set[0] if write_set else None)
    if kind == "batch_rotate":
        items = details.get("items")
        if not isinstance(items, list):
            return False
        item_keys = set()
        for item in items:
            if not isinstance(item, dict) or not _is_key_id(
                item.get("key_id")
            ):
                return False
            item_keys.add(item["key_id"])
        return item_keys == set(write_set)
    key_ids = details.get("key_ids")
    if not isinstance(key_ids, list) or sorted(key_ids) != sorted(write_set):
        return False
    return bool(details.get("policy_restored")) == bool(
        descriptor.get("policy")
    )

def _binding_matches(self, descriptor: dict, record) -> bool:
    """Whether the mirror is the SAME attempt as the operation record.

    Compares the full binding (tenant/operator/path/canonical request),
    requires an internally consistent descriptor, and -- once the mirror
    is described -- requires the record's durable details to name the
    exact same kind, key_id/items, write set and policy fact.
    """
    if descriptor.get("operation_id") != record.operation_id:
        return False
    for field in ("tenant_id", "operator_id", "path", "request_body"):
        if descriptor.get(field) != getattr(record, field):
            return False
    if not self._descriptor_consistent(descriptor, allow_undescribed=True):
        return False
    if not self._details_correspond(descriptor, record):
        return False
    return True

@staticmethod
def _event_confirms(descriptor: dict, event) -> bool:
    """Whether a durable event is exactly this mirror's commit event.

    The event id is the operation id by construction; action and tenant
    must additionally agree with the mirror. A rejected event or an
    action/tenant mismatch never confirms a commit.
    """
    if event is None or event.outcome != audit_mod.OUTCOME_SUCCESS:
        return False
    tenant = descriptor.get("tenant_id")
    if tenant is not None and event.tenant_id != tenant:
        return False
    kind = descriptor.get("kind")
    expected = descriptor.get("action") or _KIND_ACTIONS.get(kind)
    if expected is None:
        # The mirror never recorded which action the attempt commits
        # (crash between create and describe): a durable event cannot be
        # confirmed as THIS attempt's commit -- action agreement is
        # unprovable, so never clean on it.
        return False
    return event.action == expected

def _rejected_event_matches(self, descriptor: dict, record, event) -> bool:
    """Whether a durable REJECTED terminal event belongs to this mirror.

    A rejection commits no write set, but its event must still name the
    operation and carry the mirror's action and tenant; rotate/import
    rejections project the one write-set key while batch/restore events
    project no key. When the record staged its audit descriptor / result
    before the append, those durable facts must agree with the event and
    the staged response must be a refusal (never a 201). Anything less
    leaves the evidence parked.
    """
    if event is None or event.outcome != audit_mod.OUTCOME_REJECTED:
        return False
    if descriptor.get("kind") is None:
        return False
    if event.action != descriptor.get("action"):
        return False
    if event.tenant_id != descriptor.get("tenant_id"):
        return False
    kind = descriptor.get("kind")
    write_set = descriptor.get("write_set") or []
    if kind in ("rotate", "import", "encrypt"):
        if event.key_id != (write_set[0] if write_set else None):
            return False
    elif event.key_id is not None:
        return False
    details = getattr(record, "details", None)
    if isinstance(details, dict):
        audit_desc = details.get("audit")
        if isinstance(audit_desc, dict):
            if audit_desc.get("action") not in (None, event.action):
                return False
            if audit_desc.get("outcome") not in (
                None, audit_mod.OUTCOME_REJECTED
            ):
                return False
            if audit_desc.get("tenant_id") not in (None, event.tenant_id):
                return False
        result = details.get("result")
        if isinstance(result, dict) and result.get("http_status") == 201:
            # A staged 201 response cannot share an id with a rejection.
            return False
    return True

def _staged_success_response_backed(
    self, descriptor: dict, record
) -> bool:
    """Whether a staged 201 response is backed by the committed write set.

    Startup settlement uses this when the operation record persisted its
    exact success response before the commit-point append: the on-disk
    committed state must actually support that response (the named
    versions exist; a restore's key set and policy flag match). Records
    without a staged response (older bindings, crafted recovery scenes)
    skip this and rely on the artifact checks alone.
    """
    details = getattr(record, "details", None)
    if not isinstance(details, dict):
        return True
    result = details.get("result")
    if not isinstance(result, dict):
        return True
    http_status = result.get("http_status")
    response = result.get("response")
    if http_status is None and response is None:
        return True
    if not isinstance(response, dict):
        return False
    kind = descriptor.get("kind")
    tenant_id = descriptor.get("tenant_id")
    write_set = descriptor.get("write_set") or []
    # Mutating operations stage a 201; the read-only encrypt stages a 200.
    allowed_status = 200 if kind in _READ_ONLY_KINDS else 201
    if http_status != allowed_status:
        return False
    if kind in ("rotate", "import"):
        key_id = write_set[0] if write_set else None
        if response.get("key_id") != key_id:
            return False
        key = self.key_store._read_record(self.key_store._path_for(key_id))
        if key is None or key.tenant_id != tenant_id:
            return False
        if kind == "rotate":
            version = response.get("version")
            if not isinstance(version, int) or key.get_version(version) is None:
                return False
    elif kind == "batch_rotate":
        items = response.get("items")
        if not isinstance(items, list):
            return False
        response_keys = set()
        for item in items:
            if not isinstance(item, dict):
                return False
            key_id = item.get("key_id")
            if not _is_key_id(key_id):
                return False
            response_keys.add(key_id)
            key = self.key_store._read_record(
                self.key_store._path_for(key_id)
            )
            if key is None or key.tenant_id != tenant_id:
                return False
            version = item.get("version")
            if not isinstance(version, int) or key.get_version(version) is None:
                return False
        if response_keys != set(write_set):
            return False
    elif kind == "encrypt":
        # The read-only encrypt creates nothing: the key must still exist
        # for the mirror's tenant and the staged envelope must name that
        # same key and one of its existing versions. The envelope bytes
        # themselves are opaque -- only structural metadata is checked.
        from . import envelope as envelope_mod

        key_id = write_set[0] if write_set else None
        if response.get("format") != envelope_mod.FORMAT:
            return False
        if response.get("operation_id") != descriptor.get("operation_id"):
            return False
        token = response.get("envelope")
        if not isinstance(token, str) or not token:
            return False
        try:
            opened = envelope_mod.decode_envelope(token)
        except Exception:
            return False
        if opened.key_id != key_id:
            return False
        key = self.key_store._read_record(self.key_store._path_for(key_id))
        if key is None or key.tenant_id != tenant_id:
            return False
        if key.get_version(opened.version) is None:
            return False
    elif kind == "restore":
        key_ids = response.get("key_ids")
        if not isinstance(key_ids, list) or sorted(key_ids) != sorted(
            write_set
        ):
            return False
        if response.get("policy_restored") != bool(descriptor.get("policy")):
            return False
        for key_id in write_set:
            key = self.key_store._read_record(
                self.key_store._path_for(key_id)
            )
            if key is None or key.tenant_id != tenant_id:
                return False
    return True

def _committed_state_verified(self, descriptor: dict) -> bool:
    """Verify the committed write set and every surviving reference.

    Every write-set key file must exist, belong to the mirror's tenant,
    carry no unresolved pending marker of this operation and own every
    (provider_id, handle) the mirror recorded; a restore that carried a
    policy leaves the tenant's committed policy document, and an empty
    restore leaves its finalized (event-cleared) marker. The provision
    journal and a batch snapshot are post-commit housekeeping and must
    already be gone. Finally every surviving on-disk reference must be
    cross-consistent with the mirror (a missing/corrupt/duplicate/extra
    reference keeps the mirror for the next open).
    """
    if not self._descriptor_consistent(descriptor, allow_undescribed=False):
        return False
    operation_id = descriptor["operation_id"]
    journal_id = descriptor.get("journal") or operation_id
    if os.path.exists(self.key_store._provision_path(journal_id)):
        return False
    if descriptor.get("snapshot") and os.path.exists(
        self.key_store._batch_snapshot_path(descriptor["snapshot"])
    ):
        return False
    kind = descriptor.get("kind")
    tenant_id = descriptor.get("tenant_id")
    owned = set()
    for key_id in descriptor.get("write_set", []):
        record = self.key_store._read_record(self.key_store._path_for(key_id))
        if record is None or record.tenant_id != tenant_id:
            return False
        marker = getattr(record, "pending_event", None)
        if isinstance(marker, dict) and self._marker_event_id(
            marker
        ) == operation_id:
            return False
        for ver in record.versions:
            owned.add((ver.provider_id, ver.handle))
    expected = {
        (entry.get("provider_id"), entry.get("handle"))
        for entry in descriptor.get("handles", [])
        if isinstance(entry, dict)
    }
    if not expected.issubset(owned):
        return False
    if kind == "restore" and not self._committed_restore_extras_verified(
        descriptor
    ):
        return False
    if not self._surviving_artifacts_consistent(descriptor):
        return False
    return True

def _committed_restore_extras_verified(self, descriptor: dict) -> bool:
    """Committed restore policy document and empty-restore marker checks."""
    tenant_id = descriptor.get("tenant_id")
    if descriptor.get("policy"):
        doc = self._read_policy_doc(self._policy_doc_path(tenant_id))
        if doc is None:
            return False
        owner, pending = doc
        if owner != tenant_id:
            return False
        if isinstance(pending, dict) and self._marker_event_id(
            pending
        ) == descriptor.get("operation_id"):
            return False
    if not descriptor.get("write_set") and not descriptor.get("policy"):
        # An empty restore commits only its persistent marker: it must
        # survive, be finalized (event cleared) and name this tenant.
        path = descriptor.get("empty_marker")
        if not isinstance(path, str) or not os.path.exists(path):
            return False
        try:
            with open(path, "r", encoding="utf-8") as fh:
                marker = json.load(fh)
        except (OSError, ValueError):
            return False
        if not isinstance(marker, dict) or not marker.get("_empty"):
            return False
        if marker.get("tenant_id") != tenant_id or marker.get("event") is not None:
            return False
    return True

def _policy_doc_path(self, tenant_id: str) -> str:
    # Mirror PolicyStore._path_for WITHOUT constructing a PolicyStore: its
    # constructor runs outbox recovery, which a read-only verification must
    # never trigger as a side effect.

        # never trigger as a side effect.
        digest = hashlib.sha256(tenant_id.encode("utf-8")).hexdigest()
        return os.path.join(self.data_dir, "policies", digest + ".json")

    def _read_policy_doc(self, path: str):
        """Read (tenant_id, pending_event) from a policy file, side-effect free.

        Rules are not validated here -- only the owning tenant and the pending
        marker are cross-checked -- so this never instantiates PolicyStore (and
        never runs its startup outbox recovery). Returns None when the file is
        absent or unreadable.
        """
        try:
            with open(path, "r", encoding="utf-8") as fh:
                doc = json.load(fh)
        except (OSError, ValueError):
            return None
        if not isinstance(doc, dict):
            return None
        return doc.get("tenant_id"), doc.get("pending_event")

    # -- surviving-artifact cross-validation -------------------------------
    def _surviving_artifacts_consistent(self, descriptor: dict) -> bool:
        """Whether every surviving on-disk reference cross-agrees.

        Returns False when a surviving reference is missing, corrupt,
        duplicated or carries more/fewer facts than the mirror; the caller
        then keeps the whole evidence set. Absence of an artifact the attempt
        legitimately removed is fine.
        """
        try:
            self._journal_verdict(descriptor)
            kind = descriptor.get("kind")
            if kind == "batch_rotate":
                self._snapshot_verdict(descriptor)
            elif descriptor.get("snapshot"):
                return False
            if kind == "restore":
                self._restore_artifacts_verdict(descriptor)
            elif isinstance(descriptor.get("empty_marker"), str):
                return False
        except ArtifactInconsistent:
            return False
        return True

    def _journal_verdict(self, descriptor: dict) -> None:
        """Cross-check a surviving provision journal against the mirror.

        Compares the journal's operation header (operation_id/tenant/action)
        and its exact provider_id/handle SET with the mirror: a corrupt,
        duplicated or extra entry is an inconsistency. Legacy headerless
        journals keep id-only resolution, but their handle set must still
        equal the mirror's. Absence is fine. Raises ArtifactInconsistent.
        """
        operation_id = descriptor["operation_id"]
        journal_id = descriptor.get("journal") or operation_id
        path = self.key_store._provision_path(journal_id)
        if not os.path.exists(path):
            return
        try:
            with open(path, "r", encoding="utf-8") as fh:
                raw_lines = [
                    line for line in fh.read().splitlines() if line.strip()
                ]
        except OSError as exc:
            raise ArtifactInconsistent(str(exc))
        entries = []
        header = None
        for index, raw in enumerate(raw_lines):
            try:
                line = json.loads(raw)
            except ValueError:
                raise ArtifactInconsistent("corrupt provision journal line")
            if not isinstance(line, dict):
                raise ArtifactInconsistent(
                    "provision journal line is not an object"
                )
            if index == 0 and "operation_id" in line:
                header = line
                continue
            provider_id = line.get("provider_id")
            handle = line.get("handle")
            if not (
                isinstance(provider_id, str)
                and provider_id
                and isinstance(handle, str)
                and handle
            ):
                raise ArtifactInconsistent("provision journal entry is malformed")
            entries.append((provider_id, handle))
        kind = descriptor.get("kind")
        if header is not None:
            if header.get("operation_id") != journal_id:
                raise ArtifactInconsistent(
                    "provision journal header names another operation"
                )
            if kind is not None:
                if header.get("tenant_id") != descriptor.get("tenant_id"):
                    raise ArtifactInconsistent(
                        "provision journal tenant disagrees with the mirror"
                    )
                if header.get("action") != descriptor.get("action"):
                    raise ArtifactInconsistent(
                        "provision journal action disagrees with the mirror"
                    )
        pairs = set()
        for pair in entries:
            if pair in pairs:
                raise ArtifactInconsistent(
                    "duplicate handle entry in provision journal"
                )
            pairs.add(pair)
        mirrored = {
            (entry.get("provider_id"), entry.get("handle"))
            for entry in descriptor.get("handles", [])
            if isinstance(entry, dict)
        }
        if pairs != mirrored:
            raise ArtifactInconsistent(
                "provision journal handle set disagrees with the mirror"
            )

    @staticmethod
    def _marker_event_id(marker) -> Optional[str]:
        """The event id a (possibly nested) pending marker names."""
        if not isinstance(marker, dict):
            return None
        nested = marker.get("event")
        desc = nested if isinstance(nested, dict) else marker
        event_id = desc.get("event_id") if isinstance(desc, dict) else None
        return event_id if isinstance(event_id, str) else None

    def _scan_pending_markers(self, operation_id: str) -> list:
        """All surviving pending markers (key files, policy doc) naming an id."""
        found = []
        try:
            names = os.listdir(self.data_dir)
        except OSError:
            return found
        for name in names:
            if not (name.endswith(".json") and _is_key_id(name[:-5])):
                continue
            record = self.key_store._read_record(os.path.join(self.data_dir, name))
            marker = getattr(record, "pending_event", None)
            if isinstance(marker, dict) and self._marker_event_id(
                marker
            ) == operation_id:
                found.append(("key", record.key_id, marker))
        policy_dir = os.path.join(self.data_dir, "policies")
        try:
            policy_names = os.listdir(policy_dir)
        except OSError:
            return found
        for name in policy_names:
            if not name.endswith(".json"):
                continue
            path = os.path.join(policy_dir, name)
            doc = self._read_policy_doc(path)
            owner = None
            pending = None
            if doc is None:
                try:
                    with open(path, "r", encoding="utf-8") as fh:
                        raw = json.load(fh)
                except (OSError, ValueError):
                    continue
                if isinstance(raw, dict):
                    owner = raw.get("tenant_id")
                    pending = raw.get("pending_event")
            else:
                owner, pending = doc
            if isinstance(pending, dict) and self._marker_event_id(
                pending
            ) == operation_id:
                found.append(("policy", owner, pending))
        return found

    def _snapshot_verdict(self, descriptor: dict) -> None:
        """Cross-check a surviving batch snapshot against the mirror.

        Filename/event id, tenant, the exact key_id set, and every
        ``previous_b64`` image (strictly decoded into a tenant-matching,
        version-contiguous KeyRecord with no pending marker) must agree with
        the mirror and with every residual batch marker. A surviving snapshot
        the mirror never named, or a referenced but corrupt/mismatched one,
        is an inconsistency.
        """
        operation_id = descriptor["operation_id"]
        tenant_id = descriptor.get("tenant_id")
        referenced = descriptor.get("snapshot")
        expected_id = referenced or operation_id
        path = self.key_store._batch_snapshot_path(expected_id)
        present = os.path.exists(path)
        if referenced is None:
            if present:
                raise ArtifactInconsistent(
                    "unnamed batch snapshot survives for the operation"
                )
            return
        if not present:
            # Referenced but gone: legitimate only after a verified rollback;
            # the residual-marker scan decides whether files still need it.
            return
        raw = self.key_store._read_batch_snapshot(expected_id)
        if not isinstance(raw, dict):
            raise ArtifactInconsistent("batch snapshot is missing or corrupt")
        if raw.get("event_id") != expected_id:
            raise ArtifactInconsistent(
                "batch snapshot event_id disagrees with its filename"
            )
        if raw.get("tenant_id") != tenant_id:
            raise ArtifactInconsistent(
                "batch snapshot tenant disagrees with the mirror"
            )
        snapshot_keys = set()
        for entry in raw.get("keys", []):
            if not isinstance(entry, dict) or not _is_key_id(entry.get("key_id")):
                raise ArtifactInconsistent("batch snapshot key entry is malformed")
            snapshot_keys.add(entry["key_id"])
        if snapshot_keys != set(descriptor.get("write_set", [])):
            raise ArtifactInconsistent(
                "batch snapshot key set disagrees with the mirror write set"
            )
        markers = [
            marker
            for _where, _owner, marker in self._scan_pending_markers(
                operation_id
            )
            if isinstance(marker, dict) and marker.get("_batch_rotate")
        ]
        if self.key_store._validated_batch_snapshot(
            expected_id, raw, markers
        ) is None:
            raise ArtifactInconsistent(
                "batch snapshot contents or residual markers are invalid"
            )

    def _restore_artifacts_verdict(self, descriptor: dict) -> None:
        """Cross-check surviving restore markers (multi-file and empty)."""
        operation_id = descriptor["operation_id"]
        tenant_id = descriptor.get("tenant_id")
        write_set = set(descriptor.get("write_set", []))
        for where, owner, marker in self._scan_pending_markers(operation_id):
            if not isinstance(marker, dict) or not marker.get("_restore"):
                raise ArtifactInconsistent(
                    "a pending marker naming the restore is not a restore marker"
                )
            if marker.get("_empty"):
                continue
            desc = marker.get("event")
            if not isinstance(desc, dict):
                raise ArtifactInconsistent("restore marker carries no event")
            if desc.get("event_id") != operation_id:
                raise ArtifactInconsistent("restore marker names another event")
            if desc.get("action") != audit_mod.ACTION_IMPORT:
                raise ArtifactInconsistent(
                    "restore marker event action is not import"
                )
            if desc.get("tenant_id") != tenant_id or marker.get(
                "tenant_id"
            ) != tenant_id:
                raise ArtifactInconsistent(
                    "restore marker tenant disagrees with the mirror"
                )
            key_ids = marker.get("key_ids")
            if not isinstance(key_ids, list) or set(key_ids) != write_set:
                raise ArtifactInconsistent(
                    "restore marker write set disagrees with the mirror"
                )
            if bool(marker.get("policy")) != bool(descriptor.get("policy")):
                raise ArtifactInconsistent(
                    "restore marker policy flag disagrees with the mirror"
                )
            journal = marker.get("journal")
            if journal is not None and journal != operation_id:
                raise ArtifactInconsistent(
                    "restore marker journal does not name the operation"
                )
            if where == "policy" and owner != tenant_id:
                raise ArtifactInconsistent(
                    "restored policy document names another tenant"
                )
        empty_path = descriptor.get("empty_marker")
        if isinstance(empty_path, str) and os.path.exists(empty_path):
            try:
                with open(empty_path, "r", encoding="utf-8") as fh:
                    marker = json.load(fh)
            except (OSError, ValueError):
                raise ArtifactInconsistent("empty restore marker is corrupt")
            if not isinstance(marker, dict) or not marker.get("_empty"):
                raise ArtifactInconsistent("empty restore marker is malformed")
            if marker.get("tenant_id") != tenant_id:
                raise ArtifactInconsistent(
                    "empty restore marker tenant disagrees with the mirror"
                )
            event = marker.get("event")
            if event is None:
                return
            if not isinstance(event, dict):
                raise ArtifactInconsistent(
                    "empty restore marker event is malformed"
                )
            if event.get("event_id") != operation_id:
                raise ArtifactInconsistent(
                    "empty restore marker names another event"
                )
            if (
                event.get("action") != audit_mod.ACTION_IMPORT
                or event.get("tenant_id") != tenant_id
            ):
                raise ArtifactInconsistent(
                    "empty restore marker event disagrees with the mirror"
                )

    def _residual_evidence(self, descriptor: dict) -> bool:
        """Whether uncommitted-attempt artifacts still survive on disk.

        Scans the provision journal, the batch snapshot, the restore empty
        marker and every key/policy file carrying a pending marker named after
        this operation. The outbox recovery leaves these in place exactly while
        it is parking the scene (unreadable ledger, unreachable provider,
        corrupt/missing basis, id collision); while any survives the mirror
        cannot be dropped.
        """
        operation_id = descriptor["operation_id"]
        journal_id = descriptor.get("journal") or operation_id
        if os.path.exists(self.key_store._provision_path(journal_id)):
            return True
        if descriptor.get("snapshot") and os.path.exists(
            self.key_store._batch_snapshot_path(descriptor["snapshot"])
        ):
            return True
        empty_marker = descriptor.get("empty_marker")
        if isinstance(empty_marker, str) and self._pending_empty_marker(
            empty_marker, operation_id
        ):
            return True
        return bool(self._scan_pending_markers(operation_id))

    def _pending_empty_marker(self, path: str, operation_id: str) -> bool:
        """An empty-restore marker still carrying THIS pending event."""
        try:
            with open(path, "r", encoding="utf-8") as fh:
                marker = json.load(fh)
        except (OSError, ValueError):
            # Corrupt marker reference: treat as residual evidence so the
            # mirror (and the marker) stay for a later, safer open.
            return os.path.exists(path)
        if not isinstance(marker, dict):
            return os.path.exists(path)
        event = marker.get("event")
        if isinstance(event, dict):
            return event.get("event_id") == operation_id
        return False


def _is_uuid4(value: str) -> bool:
    try:
        return uuid.UUID(value).version == 4
    except (ValueError, AttributeError, TypeError):

def _resolve_committed_operation(store, policy_store, record, event):
    """Rebuild the terminal response of a committed-but-unfinished operation.

    Runs during startup recovery after the key/restore outbox recovery has
    made the mutation durable. The audit event named after the operation_id
    is the durable fact: a ``success`` event rebuilds the original 201
    response, while a ``rejected`` event rebuilds the exact 403/404/409
    terminal (its state, error body and audit projection) from the recorded
    action/key_id and the current tenant state. Returns
    ``(http_status, response)``.
    """
    op_id = record.operation_id
    details = record.details or {}
    kind = details.get("kind")
    tenant_id = record.tenant_id
    operator_id = record.operator_id

    def error(status: int, message: str):
        return status, {"error": message, "operation_id": op_id}

    if event.outcome == audit_mod.OUTCOME_REJECTED:
        action = event.action
        terminal = details.get("terminal")
        # A batch rotation is AUTHORIZED as rotate even though its audit
        # action is batch_rotate; map back for the legacy no-terminal policy
        # reconstruction below.
        policy_action = (
            audit_mod.ACTION_ROTATE
            if action == audit_mod.ACTION_BATCH_ROTATE
            else action
        )

        def message_for(status: int) -> str:
            if status == 403:
                return "action not permitted by policy"
            if status == 409:
                if kind == "restore":
                    return "backup target already contains this data"
                return "key_id already exists for this tenant"
            if kind == "restore":
                return "tenant backup not found"
            return "key not found"

        # The original terminal status is persisted with the event: replay it
        # verbatim, so a policy change or a state change after the crash can
        # never turn a 403 into a 404/409 or vice versa.
        if terminal in (403, 404, 409):
            return error(terminal, message_for(terminal))

        # Older records without the stashed terminal: infer once from the
        # durable action and the current state.
        # A policy denial outranks existence: it is reconstructed whenever the
        # tenant's policy currently rejects this operator/action.
        if not policy_store.is_allowed(tenant_id, policy_action, operator_id):
            return error(403, message_for(403))
        if kind == "restore":
            # A same-tenant conflict is reconstructed when any key from the
            # write set now belongs to the tenant, a restored policy exists,
            # or (empty bundle) the persistent empty-restore marker is on
            # disk. Every other rejection (in-bundle tenant mismatch, foreign
            # occupation) replays as 404. Restore events always carry
            # key_id null.
            for key_id in details.get("key_ids", []):
                raw = store.read_raw(key_id)
                if raw is not None and raw.tenant_id == tenant_id:
                    return error(409, message_for(409))
            if details.get("policy_restored") and policy_store.get(
                tenant_id
            ) is not None:
                return error(409, message_for(409))
            digest = hashlib.sha256(tenant_id.encode("utf-8")).hexdigest()
            marker = os.path.join(
                store.data_dir, "restore-empty-" + digest + ".json"
            )
            if os.path.exists(marker):
                return error(409, message_for(409))
            return error(404, message_for(404))
        if kind == "import":
            key_id = event.key_id or details.get("key_id")
            raw = store.read_raw(key_id) if is_valid_key_id(key_id) else None
            if raw is not None and raw.tenant_id == tenant_id:
                return error(409, message_for(409))
            return error(404, message_for(404))
        # rotate (and any unknown shape): a rejected rotate means the key was
        # unknown or foreign at commit time and no version was appended.
        return error(404, message_for(404))

    if kind == "rotate":
        key_id = event.key_id or details.get("key_id")
        key = store.get(key_id, tenant_id)
        if key is not None:
            # The committed version is the one whose creation time equals the
            # event timestamp; fall back to the current pointer.
            ver = None
            for candidate in key.versions:
                if candidate.created_at == event.timestamp:
                    ver = candidate
                    break
            if ver is None:
                ver = key.current
            return (
                201,
                {
                    "key_id": key_id,
                    "version": ver.version,
                    "algorithm": ver.algorithm,
                    "public_key": ver.public_key,
                    "operation_id": op_id,
                },
            )
    if kind == "batch_rotate":
        # The batch's single event carries key_id null; the request-order
        # item set is durable in details. Rebuild each item's committed
        # version (the one minted at the event timestamp, else the current
        # pointer). A key that is no longer readable makes the projection fall
        # back to operation_id-only rather than fabricating a version.
        result_items = []
        complete = True
        for one in details.get("items", []):
            key_id = one.get("key_id")
            key = (
                store.get(key_id, tenant_id)
                if is_valid_key_id(key_id)
                else None
            )
            if key is None:
                complete = False
                break
            ver = None
            for candidate in key.versions:
                if candidate.created_at == event.timestamp:
                    ver = candidate
                    break
            if ver is None:
                ver = key.current
            result_items.append(
                {
                    "key_id": key_id,
                    "version": ver.version,
                    "algorithm": ver.algorithm,
                    "public_key": ver.public_key,
                }
            )
        if complete:
            return 201, {"items": result_items, "operation_id": op_id}
    if kind == "import":
        key_id = event.key_id or details.get("key_id")
        key = store.get(key_id, tenant_id)
        if key is not None:
            body = key.to_create_response()
            body["operation_id"] = op_id
            return 201, body
    if kind == "restore":
        return (
            201,
            {
                "tenant_id": tenant_id,
                "key_ids": details.get("key_ids", []),
                "policy_restored": details.get("policy_restored", False),
                "operation_id": op_id,
            },
        )
    # Cannot rebuild the projection; the mutation did commit, so keep it
    # succeeded with an operation_id-only body rather than pending forever.
    return 201, {"operation_id": op_id}


def serve(host: str, port: int, data_dir: str) -> None:
    """Run the HTTP server until interrupted."""
    audit_log = AuditLog(data_dir)

    Raised when no provider chain is configured or the requested
    ``provider_id`` is not one of the chain entries. Surfaced as HTTP
    ``400`` / CLI exit code ``2`` with the field named, and raised before
    any state write, provider swap or audit event (zero side effects).
    """


class MaterialTriple(NamedTuple):
    """The provider-owned result of generate/rotate/import_material."""

    handle: str
    public_key: Optional[str]
    encrypted_material: str


class ExportedMaterial(NamedTuple):
    """Result of export_material: material plus its public component."""

    public_key: Optional[str]
    encrypted_material: str


def _b64e(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


def _b64d(text: str) -> bytes:
    return base64.urlsafe_b64decode(text + "=" * (-len(text) % 4))


def _require_triple(result, operation: str) -> MaterialTriple:
    """Validate a generate/rotate/import result has a handle and material."""
    if not isinstance(result, dict):
        raise ProviderUnavailable(
            "provider %s returned a non-object from %s"
            % ("external", operation)
        )
    handle = result.get("handle")
    material = result.get("encrypted_material")
    if not isinstance(handle, str) or not handle:
        raise ProviderUnavailable(
            "provider returned an empty handle from %s" % operation
        )
    if not isinstance(material, str) or not material:
        raise ProviderUnavailable(
            "provider returned empty encrypted_material from %s" % operation
        )
    public_key = result.get("public_key")
    if public_key is not None and not isinstance(public_key, str):
        raise ProviderUnavailable(
            "provider returned an invalid public_key from %s" % operation
        )
    return MaterialTriple(
        handle=handle, public_key=public_key, encrypted_material=material
    )


class KeyProvider:
    """Abstract provider; concrete providers implement the five operations."""

    provider_id = ""
    capabilities = {"algorithms": (), "operations": ()}

    def configure(self, data_dir: str) -> None:
        """Bind any persistent state to the data directory (optional)."""

    def generate(self, algorithm: str) -> MaterialTriple:
        raise NotImplementedError

    def rotate(self, algorithm: str) -> MaterialTriple:
        raise NotImplementedError

    def import_material(
        self,
        algorithm: str,
        public_key: Optional[str],
        material: str,
    ) -> MaterialTriple:
        raise NotImplementedError

    def export_material(self, handle: str) -> ExportedMaterial:
        raise NotImplementedError

    def delete(self, handle: str) -> None:
        raise NotImplementedError

    def health(self) -> bool:
        """Optional KMS/HSM readiness probe.

        Built-in providers are always ready. An external provider may omit
        this method (a missing probe means healthy); :class:`_SafeProvider`
        enforces the bool/exception contract on objects that supply one.
        """
        return True

    def supports(self, algorithm: str, operation: str) -> bool:
        caps = getattr(self, "capabilities", {}) or {}
        return (
            algorithm in caps.get("algorithms", ())
            and operation in caps.get("operations", ())
        )


def _validate_external(obj) -> None:
    """Check a factory-built object satisfies the provider contract."""
    provider_id = getattr(obj, "provider_id", None)
    if not isinstance(provider_id, str) or not provider_id:
        raise ProviderUnavailable(
            "provider factory returned an object without a non-empty provider_id"
        )
    caps = getattr(obj, "capabilities", None)
    if not isinstance(caps, dict):
        raise ProviderUnavailable(
            "provider %r has no capabilities mapping" % provider_id
        )
    algorithms = caps.get("algorithms")
    operations = caps.get("operations")
    if not isinstance(algorithms, (list, tuple)) or not isinstance(
        operations, (list, tuple)
    ):
        raise ProviderUnavailable(
            "provider %r capabilities must list algorithms and operations"
            % provider_id
        )
    missing = [a for a in SUPPORTED_ALGORITHMS if a not in algorithms]
    if missing:
        raise ProviderUnavailable(
            "provider %r lacks required algorithms: %s"
            % (provider_id, ", ".join(missing))
        )
    missing_ops = [op for op in OPERATIONS if op not in operations]
    if missing_ops:
        raise ProviderUnavailable(
            "provider %r lacks required operations: %s"
            % (provider_id, ", ".join(missing_ops))
        )
    for name in OPERATIONS:
        if not callable(getattr(obj, name, None)):
            raise ProviderUnavailable(
                "provider %r is missing a callable %s() operation"
                % (provider_id, name)
            )
    configure = getattr(obj, "configure", None)
    if configure is not None and not callable(configure):
        raise ProviderUnavailable(
            "provider %r has a non-callable configure attribute" % provider_id
        )
    # health() is optional: no attribute means always healthy. A present but
    # non-callable health is a contract failure like any other method.
    health = getattr(obj, "health", None)
    if health is not None and not callable(health):
        raise ProviderUnavailable(
            "provider %r has a non-callable health attribute" % provider_id
        )


class _SafeProvider:
    """Adapter around an external provider enforcing the error contract.

    ProviderError subtypes pass through unchanged; any other exception the
    external module raises is normalized to ProviderUnavailable so a backend
    fault always surfaces as 503 and never as a 500 or a fallback.
    """

    def __init__(self, inner) -> None:
        self._inner = inner
        self.provider_id = inner.provider_id
        self.capabilities = inner.capabilities

    def configure(self, data_dir: str) -> None:
        try:
            configure = getattr(self._inner, "configure", None)
            if configure is not None:
                configure(data_dir)
        except ProviderError:
            raise
        except Exception as exc:
            raise ProviderUnavailable(
                "provider %r failed to initialize" % self.provider_id
            ) from exc

    def _call(self, name: str, *args):
        method = getattr(self._inner, name)
        try:
            return method(*args)
        except ProviderError:
            raise
        except Exception as exc:
            raise ProviderUnavailable(
                "provider %r operation %s failed" % (self.provider_id, name)
            ) from exc

    def generate(self, algorithm: str) -> MaterialTriple:
        return _require_triple(self._call("generate", algorithm), "generate")

    def rotate(self, algorithm: str) -> MaterialTriple:
        return _require_triple(self._call("rotate", algorithm), "rotate")

    def import_material(self, algorithm, public_key, material) -> MaterialTriple:
        return _require_triple(
            self._call("import_material", algorithm, public_key, material),
            "import_material",
        )

    def export_material(self, handle: str) -> ExportedMaterial:
        result = self._call("export_material", handle)
        if not isinstance(result, dict):
            raise ProviderUnavailable(
                "provider returned a non-object from export_material"
            )
        material = result.get("encrypted_material")
        if not isinstance(material, str) or not material:
            raise ProviderUnavailable(
                "provider returned empty encrypted_material from export_material"
            )
        public_key = result.get("public_key")
        if public_key is not None and not isinstance(public_key, str):
            raise ProviderUnavailable(
                "provider returned an invalid public_key from export_material"
            )
        return ExportedMaterial(
            public_key=public_key, encrypted_material=material
        )

    def delete(self, handle: str) -> None:
        # Idempotent by contract; even so, a backend fault on delete is a 503
        # (the caller may retry, and delete must remain idempotent).
        self._call("delete", handle)

    def health(self) -> bool:
        """Optional readiness probe normalized to a bool.

        A provider without a ``health`` method is treated as ready. A method
        that raises, returns a non-bool, or returns ``False`` reports
        unavailable; any backend text is swallowed here and never reaches a
        client.
        """
        method = getattr(self._inner, "health", None)
        if method is None:
            # Missing health() means healthy by contract.
            return True
        try:
            result = method()
        except Exception:
            return False
        # Only the exact bool True is healthy; a bool False, a truthy
        # non-bool (1, "yes", ...) and any other object mean unavailable.
        return result is True


class LocalProvider(KeyProvider):
    """Built-in software provider.

    Raw material never lands in a key file: each generated/imported key is
    wrapped with AES-256-GCM under a data-encryption key kept in
    ``local.dek`` (0600), and only the wrapped blob plus an opaque handle is
    persisted. A small registry (``local-registry.json``, 0600) maps each
    handle to its algorithm and wrapped blob, so ``export_material(handle)``

        raise
    finally:
        if fd >= 0:
            os.close(fd)
    return journal_id, path

def _append_provision(self, path: str, provider_id: str, handle: str) -> None:
    """Durably record one minted handle in an attempt's journal.

    The journal is rewritten atomically (temp file, fsync, 0600 rename)
    rather than appended in place: a crash mid-write can never tear a
    line and silently lose a handle record, which would orphan the
    backend object. Callers always hold the attempt's key locks, so the
    read-modify-write is serialized against every other writer.
    """
    entry = {"provider_id": provider_id, "handle": handle}
    line = json.dumps(entry, separators=(",", ":")) + "\n"
    try:
        with open(path, "r", encoding="utf-8") as fh:
            existing = fh.read()
    except OSError:
        existing = ""
    directory = os.path.dirname(path)
    fd, tmp_path = tempfile.mkstemp(dir=directory, suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            fh.write(existing + line)
            fh.flush()
            os.fsync(fh.fileno())
        os.chmod(tmp_path, 0o600)
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise

def _discard_provision_journal(self, path: str) -> bool:
    """Drop an attempt's journal after it committed or rolled back.

    Returns True when the journal is gone (including an already-absent
    one); a removal failure leaves the journal in place for the next
    open's recovery sweep instead of being silently swallowed.
    """
    try:
        os.unlink(path)
        return True
    except FileNotFoundError:
        return True
    except OSError:
        return False

def _delete_provisioned_handle(self, provider_id: str, handle: str) -> bool:
    """Delete one uncommitted handle. Returns True on success.

    A cleanup failure is never silently swallowed: False keeps the
    attempt's provision journal on disk so the next open retries the
    delete. Crash cleanup may need the local backend before any request
    configured it (this never imports an external module:factory
    provider); a missing/inactive provider whose handle cannot be reached
    is likewise reported, not hidden.
    """
    if provider_id == LOCAL_PROVIDER_ID:
        try:
            provider_mod.configure_local(self.data_dir)
        except ProviderUnavailable:
            return False
    try:
        provider = self._provider_for(provider_id)
    except ProviderUnavailable:
        return False
    try:
        provider.delete(handle)
    except Exception:
        return False
    return True

def _restore_marker_journals(self) -> set:
    """Journal ids referenced by still-present outbox markers.

    A multi-file restore transaction is resolved by the
    RestoreCoordinator and a multi-key batch-rotation group by
    _recover_batch_rotations; their journals must not be reaped here even
    if its shared event is not in the ledger yet (the coordinator/group
    recovery either commits and keeps the handles, or rolls the whole
    group back and deletes them). A single-key rotate/import marker
    carrying a journal is deferred as well whenever its ledger append
    could not be settled earlier in this same open: deleting its handles
    before the event is durable would orphan the record the next open
    commits. Markers can live on a key file or, for a policy-only restore,
    in the policies directory.
    """
    referenced = set()

    def consider(marker) -> None:
        if not isinstance(marker, dict):
            return
        journal_id = marker.get("journal")
        if isinstance(journal_id, str) and journal_id:
            referenced.add(journal_id)

    try:
        names = os.listdir(self.data_dir)
    except OSError:
        names = []
    for name in names:
        if name.endswith(".json") and is_valid_key_id(name[:-5]):
            record = self._read_record(os.path.join(self.data_dir, name))
            if record is not None:
                consider(record.pending_event)
    policy_dir = os.path.join(self.data_dir, "policies")
    try:
        policy_names = os.listdir(policy_dir)
    except OSError:
        policy_names = []
    for name in policy_names:
        if not name.endswith(".json"):
            continue
        try:
            with open(
                os.path.join(policy_dir, name), "r", encoding="utf-8"
            ) as fh:
                doc = json.load(fh)
        except (OSError, ValueError):
            continue
        if isinstance(doc, dict):
            consider(doc.get("pending_event"))
    return referenced

def _rollback_provision_entries(self, entries) -> bool:
    """Delete handles recorded by an uncommitted attempt.

    Returns True only when every handle was deleted (or its provider
    cannot be reached but is not local — see _delete_provisioned_handle);
    a single failed delete means False and the journal must be retained
    for a retry on the next open. Deletes stay idempotent.
    """
    cleaned = True
    for provider_id, handle in entries:
        if not self._delete_provisioned_handle(provider_id, handle):
            cleaned = False
    return cleaned

def _recover_provisions(self) -> None:
    """Settle provision journals left by attempts that did not finish.

    Resolution is driven purely by the ledger event named after the
    journal (the operation/event id):

    * a durable ``success`` event is the commit point -- the minted
      handles are now owned by the records and stay, the journal is
      removed;
    * no event, or a durable ``rejected`` event (a bound provider-failure
      terminal), means the attempt never owned the handles -- every
      recorded handle is deleted idempotently and the journal is removed
      only once every delete succeeds;
    * an unreadable ledger, a non-UUID journal or a failed handle delete
      leaves everything in place for the next open.

    Journals still referenced by a restore marker are deferred to the
    RestoreCoordinator. Nothing here imports a provider when there are no
    handles to reap, so opening a store for plain reads stays
    provider-free.
    """
    deferred = (
        self._restore_marker_journals()
        | self.batch_recovery_journal_ids()
    )
    directory = os.path.join(self.data_dir, self._PROVISION_DIR)
    try:
        names = os.listdir(directory)
    except OSError:
        return
    for name in names:
        if not name.endswith(".json"):
            continue
        journal_id = name[:-5]
        if journal_id in deferred:
            continue
        path = os.path.join(directory, name)
        try:
            with open(path, "r", encoding="utf-8") as fh:
                lines = fh.readlines()
        except OSError:
            continue
        entries = []
        for line in lines:
            line = line.strip()
            if not line:
                continue
            try:
                entry = json.loads(line)
            except ValueError:
                continue
            if not isinstance(entry, dict):
                continue
            provider_id = entry.get("provider_id")
            handle = entry.get("handle")
            if isinstance(provider_id, str) and provider_id and isinstance(
                handle, str
            ) and handle:
                entries.append((provider_id, handle))
        try:
            is_uuid4 = uuid.UUID(journal_id).version == 4
        except (ValueError, AttributeError):
            # An unidentifiable journal can never be resolved against an
            # event: leave it for manual/operator resolution rather than
            # deleting possibly-committed material.
            continue
        if not is_uuid4:
            continue
        event = None
        try:
            event = self.audit.get_event(journal_id)
        except LedgerError:
            # Cannot decide right now; leave the whole journal for a
            # later open rather than deleting committed material.
            continue
        if event is not None and event.outcome == audit_mod.OUTCOME_SUCCESS:
            if self._journal_event_is_foreign_success(journal_id, event):
                # A durable success carries this id but its action or
                # tenant disagrees with the journal's operation header:
                # an id collision, neither commit nor rollback is
                # provable. Park the whole journal for resolution.
                continue
            # Committed: handles belong to the durable records; housekeep
            # the journal. A failed unlink simply retries on next open.
            self._discard_provision_journal(path)
            continue
        # Event absent (crash/rollback) or a durable rejected terminal:
        # the attempt never owned the handles. Retain the journal until
        # every handle delete actually succeeds.
        if self._rollback_provision_entries(entries):
            self._discard_provision_journal(path)

def drop_provision_journal(self, journal_id: str) -> bool:
    """Remove an attempt journal after it committed or fully rolled back.

    Returns True when no journal remains. A failed unlink keeps it for
    startup recovery.
    """
    if not journal_id:
        return True
    return self._discard_provision_journal(self._provision_path(journal_id))

def rollback_provision_journal(self, journal_id: str) -> bool:
    """Delete every handle an uncommitted attempt journaled, then drop it.

    Used by the request path when an import/rotate/restore aborts before
    its commit point (provider fault, refused conflict, ledger failure).
    The journal is removed only once every recorded handle has been
    deleted; a failed backend delete retains it so the next open retries
    — cleanup failures are reported, never swallowed. Idempotent.
    """
    if not journal_id:
        return True
    entries = self.read_provision_journal(journal_id)
    if not self._rollback_provision_entries(entries):
        return False
    return self.drop_provision_journal(journal_id)

def _abort_provision(self, journal_id: str, adopted=()) -> None:
    """Scrub handles of an aborted attempt and reconcile its journal.

    Deletes the still-known ``(provider, handle)`` pairs directly and then
    the durable journal (which covers handles whose entries were recorded
    but whose in-memory pair the aborting frame no longer holds); deletes
    are idempotent. Raises ProviderUnavailable when any delete cannot be
    verified -- the journal then stays on disk and startup retries -- so a
    cleanup failure is a 503, never a silent orphan.
    """
    cleaned = self._release_handles(adopted)
    if not self.rollback_provision_journal(journal_id):
        cleaned = False
    if not cleaned:
        raise ProviderUnavailable(
            "could not delete a handle provisioned by an aborted attempt; "
            "cleanup will be retried at startup"
        )

    try:
        os.unlink(self._path_for(key_id))
    except FileNotFoundError:
        pass

@contextmanager
def _key_locks_deadline(self, key_id: str, deadline) -> Iterator[None]:
    """Take the in-process and fcntl locks against one shared deadline."""
    with self._timed_inproc(key_id, deadline), self._file_lock(
        key_id, deadline
    ):
        yield

@contextmanager
def key_locks(self, key_id: str, timeout: Optional[float] = None) -> Iterator[None]:
    """Acquire the in-process and cross-process locks for one key_id.

    With a finite ``timeout`` both locks share one deadline and a wait
    beyond it raises :class:`LockTimeout` with nothing held.
    """
    if timeout is None:
        with self._key_lock(key_id), self._file_lock(key_id):
            yield
    else:
        with self._key_locks_deadline(
            key_id, time.monotonic() + timeout
        ):
            yield

@contextmanager
def multi_key_locks(
    self, key_ids, timeout: Optional[float] = None
) -> Iterator[None]:
    """Acquire the per-key locks for many key_ids, in sorted order.

    A fixed acquisition order keeps this deadlock-free against the
    restore transaction, which also takes its key locks sorted. With a
    finite ``timeout`` the whole acquisition shares one deadline.
    """
    deadline = None if timeout is None else time.monotonic() + timeout
    acquired = []
    try:
        for key_id in sorted(set(key_ids)):
            if deadline is None:
                lock_cm = self.key_locks(key_id)
            else:
                lock_cm = self._key_locks_deadline(key_id, deadline)
            lock_cm.__enter__()
            acquired.append(lock_cm)
        yield
    finally:
        for lock_cm in reversed(acquired):
            lock_cm.__exit__(None, None, None)

"""A fake external KMS/HSM provider for recovery tests.

Loaded through the ``module:factory`` mechanism (``KEYMGR_PROVIDER``). State
lives in a JSON file named by ``FAKE_KMS_STATE`` so several *processes* (the
CLI, a server, a recovery sweep) share one backend, exactly like a real KMS.
Fault injection is driven by a JSON file named by ``FAKE_KMS_FAULTS``:

    {
      "unreachable": true,          # every call fails as a backend outage
      "fail": {"delete": true, ...} # per-operation failures
      "sleep": {"rotate": 5.0},     # per-operation pre-call delay (seconds)
      "health": false,              # health() returns False (unavailable)
      "health_raises": true,        # health() raises (treated as unavailable)
      "health_nonbool": "yes",      # health() returns a non-bool (unavailable)
      "health_sleep": 6.0,          # health() blocks past the reconnect budget
      "provider_id": "fakekms-alt"  # override the factory's provider_id
    }

Materials are stored base64-wrapped with a static prefix so nothing here ever
resembles plaintext, and handles are random UUIDs recorded in the state file.
"""

import base64
import json
import os
import threading
import time
import uuid

PROVIDER_ID = "fakekms"

_lock = threading.Lock()


def _state_path():
    return os.environ["FAKE_KMS_STATE"]


def _faults_path():
    return os.environ.get("FAKE_KMS_FAULTS", "")


def _load_state():
    try:
        with open(_state_path(), "r", encoding="utf-8") as fh:
            return json.load(fh)
    except (OSError, ValueError):
        return {"handles": {}}


def _save_state(state):
    path = _state_path()
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(state, fh)
        fh.flush()
        os.fsync(fh.fileno())
    os.replace(tmp, path)


def _faults():
    path = _faults_path()
    if not path:
        return {}
    try:
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
    except (OSError, ValueError):
        return {}
    return data if isinstance(data, dict) else {}


_call_counts = {}


def reset():
    """Clear per-process fault counters (called by the test fixture)."""
    _call_counts.clear()


def _check_fault(op):
    faults = _faults()
    sleep = faults.get("sleep")
    if isinstance(sleep, dict) and op in sleep:
        time.sleep(float(sleep[op]))
    if faults.get("unreachable"):
        raise RuntimeError("backend is unreachable")
    fail = faults.get("fail")
    if isinstance(fail, dict) and fail.get(op):
        raise RuntimeError("backend failure in %s" % op)
    fail_after = faults.get("fail_after")
    if isinstance(fail_after, dict) and op in fail_after:
        count = _call_counts.get(op, 0) + 1
        _call_counts[op] = count
        if count > int(fail_after[op]):
            raise RuntimeError("backend failure in %s" % op)


def _wrap(material):
    return "fk1." + base64.urlsafe_b64encode(material.encode("utf-8")).decode(
        "ascii"
    )


def _unwrap(blob):
    if not isinstance(blob, str) or not blob.startswith("fk1."):
        raise RuntimeError("not a fakekms blob")
    return base64.urlsafe_b64decode(blob[4:].encode("ascii")).decode("utf-8")


class FakeKmsProvider:
    capabilities = {
        "algorithms": ["AES256", "RSA2048"],
        "operations": [
            "generate",
            "rotate",
            "import_material",
            "export_material",
            "delete",
        ],
    }

    def __init__(self):
        # The id can be overridden per process (FAKE_KMS_PROVIDER_ID) so a
        # reconnect can install a provider carrying a different provider_id,
        # exercising the pending-operation displacement rule.
        self.provider_id = os.environ.get("FAKE_KMS_PROVIDER_ID", PROVIDER_ID)

    def configure(self, data_dir):
        _check_fault("configure")

    def health(self):
        """Optional readiness probe driven by the faults file."""
        faults = _faults()
        if faults.get("health_raises"):
            raise RuntimeError("health endpoint is failing")
        if "health_nonbool" in faults:
            return faults.get("health_nonbool")
        if "health_sleep" in faults:
            time.sleep(float(faults["health_sleep"]))
        if "health" in faults:
            return bool(faults.get("health"))
        # Default: healthy unless the backend is globally unreachable.
        return not faults.get("unreachable")

    def _mint(self, algorithm, public_key, material):
        _check_fault("mint")
        handle = uuid.uuid4().hex
        with _lock:
            state = _load_state()
            state["handles"][handle] = {
                "algorithm": algorithm,
                "public_key": public_key,
                "material": _wrap(material),
            }
            _save_state(state)
        return {
            "handle": handle,
            "public_key": public_key,
            "encrypted_material": _wrap(material),
        }

    def generate(self, algorithm):
        _check_fault("generate")
        from keymgr.crypto import generate_key

        generated = generate_key(algorithm)
        return self._mint(
            algorithm, generated.public_material, generated.private_material
        )

    def rotate(self, algorithm):
        _check_fault("rotate")
        return self.generate(algorithm)

    def import_material(self, algorithm, public_key, material):
        _check_fault("import_material")
        if not isinstance(material, str) or not material:
            raise RuntimeError("empty material")
        return self._mint(algorithm, public_key, material)

    def export_material(self, handle):
        _check_fault("export_material")
        with _lock:
            state = _load_state()
            entry = state["handles"].get(handle)
            if entry is None:
                raise RuntimeError("unknown handle")
            return {
                "public_key": entry["public_key"],
                "encrypted_material": _unwrap(entry["material"]),
            }

    def delete(self, handle):
        _check_fault("delete")
        with _lock:
            state = _load_state()
            if handle in state["handles"]:
                del state["handles"][handle]
                _save_state(state)


def make_provider():
    faults = _faults()
    if faults.get("factory_fails"):
        raise RuntimeError("fake factory is failing")
    if faults.get("factory_sleep"):
        time.sleep(float(faults["factory_sleep"]))
    return FakeKmsProvider()

